			/**
			 * 반려 팝업 호출
			 * 
			 * @param pfCallback - 콜백 함수 (Optional)
			 */
			function openRejectPopup(pfCallback){

			    var appId = "app/itgcms/common/popup/CmmnInputCausePopup";
			    
			    //팝업 호출 파라메터
			    var initValue = {
			        "param" : {
			            "causeTitle" : "반려 사유",
			            "causeDesc" : "반려 사유를 정확히 입력해야 합니다.",
			            "causeMaxLen" : "2000"  // 사유입력 최대 길이 (DB 칼럼 길이)
			        }
			    };
			    
			    util.Dialog.open(app, appId, "권한 신청 반려 사유 입력", 530, 360, function(/*cpr.events.CUIEvent*/ e){
			        
			        /*
			         * 다이얼로그 close 이벤트 핸들러(닫기 동작시 반환되는 값에 대한 처리)
			         * 다이얼로그가 이미 닫혀진 상태이기 때문에 다이얼로그 관련 이벤트리스너는 발생하지 않습니다.
			         */        
			        /**@type cpr.controls.Dialog*/
			        var dialog = e.control;
			        var returnValue = dialog.returnValue;
			        
			        /*
			         * returnValue 처리
			         * returnValue가 단일값을 경우 그대로 사용할 수 있으며, JSON 데이터일 경우 key값을 통해 value를 받을 수 있습니다. 
			         */        
			        if(!ValueUtil.isNull(returnValue)){
			            /** @type cpr.data.DataMap */
			            util.DataMap.setValue(app, "dmRejectAuthAply", "RJCT_CS_CN", returnValue.getValue("CS_TXT"));
			            console.log("=== dmRejectAuthAply: ", app.lookup("dmRejectAuthAply").getDatas());
			            
			            if (typeof pfCallback == "function") {
			                pfCallback();
			            }
			        }
			               
			    }, initValue);  
			}

			/**
			 * 화면 CRUD에 따른 기능 처리
			 * @param {"CREATE" | "UPDATE" |"READ"} psType 상세 표시 타입
			 */
			function setCrud(psType){
			    
			    if (psType == "CREATE"){
			        util.Control.setVisible(app, true,  ["btnReject", "btnApproval"]);  //반려, 승인
			        util.Control.setVisible(app, false,  ["btnClose", "btnCancel"]);  //닫기, 신청취소
			    } else if (psType == "READ"){
			        // 관리자 유무 판명하여, 관리자가 아닌 신청자로 진입했을 때, 신청취소 노출처리
			        var vbIsAdmin = app.getAppProperty("isAdmin");
			        if (vbIsAdmin) {
			            util.Control.setVisible(app, false,  ["btnReject", "btnApproval", "btnCancel"]);  //반려, 승인, 신청취소
			            util.Control.setVisible(app, true,  ["btnClose"]);  //닫기
			        } else {
			            util.Control.setVisible(app, false,  ["btnReject", "btnApproval"]);  //반려, 승인
			            util.Control.setVisible(app, true,  ["btnClose", "btnCancel"]);  //닫기, 신청취소
			        }
			    }
			}


