			/**
			 * 단위업무 메뉴권한 활성화 여부 체크
			 * 
			 * @param   {cpr.data.IDataRow}   voRow - 선택된 로우
			 * @return {Boolean} 활성화 여부
			 */
			function _isUntTaskwkMenuAuthrtEnabled(voRow) {
			    
			    // 단위업무 메뉴신청 표시 조건 (여가부/중앙관리기관:한국청소년상담복지개발원/시도 시군구 수행기관:도청 시청 군청 구청)
			    var vsInstTypeSeCd = voRow.getValue("APLY_INST_TYPE_SE_CD");
			    var vsUntTaskwkSeCd = voRow.getValue("UNT_TASKWK_SE_CD");
			    var vsInstNm = voRow.getValue("APLY_INST_NM");
			    
			    if (vsInstTypeSeCd == "1" /* 여성가족부 */
			            || (vsInstTypeSeCd == "4" /* 중앙관리기관 */ && vsInstNm == "한국청소년상담복지개발원")
			            || (vsUntTaskwkSeCd == "U01" /* 지자체청소년안전망 */ 
			                && (vsInstTypeSeCd == "5" || vsInstTypeSeCd == "8"))   /* 시도 및 시군구 수행기관 */
			    ) {
			        return true;
			    }
			    return false;
			}

